C++

```cpp
#include <bits/stdc++.h>
using namespace std;

int n, k;
int a[100010];
int cnt[100010];
string s;
int main()
{
	cin >> n >> k >> s;
	for(int i = 0 ; i < n ; i ++) {
		a[i+1] = s[i] == '1';
		cnt[i+1] = cnt[i] + a[i+1];
	}
	deque<int> que;
	stack<int> ans;
	for(int i = 1 ; i <= n ; i ++) {
		if(a[i] == 1) {
			que.push_back(1);
		}
		else if(k >= cnt[i]) {
			k -= cnt[i];
			que.push_front(0);
		} else {
			for(int j = n ; j > i ; j --) {
				ans.push(a[j]);
			}
			while(k--) {
				ans.push(que.back());
				que.pop_back();
			}
			ans.push(0);
			break;
		}
	}
	while(que.size()) {
		ans.push(que.back());
		que.pop_back();
	}
	while(ans.size()) {
		cout << ans.top();
		ans.pop();
	}
}
```

**Java**

```java
import java.util.*;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), k = sc.nextInt();
        String str = sc.next();
        StringBuilder ans = new StringBuilder();
        int cnt = 0;		//记录1的数量
        for(int i = 0 ; i < str.length() ; i ++) {
            if(str.charAt(i) == '1') {
                cnt ++;
            } else {		//如果当前是0
                if(k >= cnt) {		//如果足够移到所有1的前面，就移过去
                    k -= cnt;
                    ans.append("0");
                } else {//否则说明k不够用了，就将当前的0往前移k位，也就是将剩余的cnt-k个1放入ans，再当前位的0放进去，再将剩余的k个1放进去，就相当于0往前移k位。
                    ans.append("1".repeat(cnt - k));
                    ans.append("0");
                    ans.append("1".repeat(k));
                    ans.append(str.substring(i+1));		//此时直接将后面剩余的所有字符都存入ans中并结束循环
                    cnt = 0;	//将cnt置为0，防止之后更新
                    break;
                }
            }
        }
        while(cnt-- > 0) {		//在k足够大的情况里不会在for循环内部结束，所以需要手动将1放入ans
            ans.append("1");
        }
        System.out.println(ans);
    }
}
```

