import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        String s = sc.next();

        StringBuilder ans = new StringBuilder();
        int cnt = 0; // 当前遇到的 '1' 的个数

        for (int i = 0; i < n; i++) {
            char ch = s.charAt(i);
            if (ch == '1') {
                cnt++;
            } else { // ch == '0'
                if (k >= cnt) {
                    // 能将这个 '0' 移到所有已遇到 '1' 的前面
                    ans.append('0');
                    k -= cnt;
                } else {
                    // 只能向前移动 k 位
                    // 追加 cnt - k 个 '1'
                    ans.append("1".repeat(cnt - k));
                    // 追加 '0'
                    ans.append('0');
                    // 追加 k 个 '1'
                    ans.append("1".repeat(k));
                    // 剩余部分直接拼入并结束
                    ans.append(s.substring(i + 1));
                    cnt = 0; // 防止后面重复添加
                    break;
                }
            }
        }

        // 补上末尾剩余的 '1'
        if (cnt > 0) {
            ans.append("1".repeat(cnt));
        }

        System.out.println(ans);
    }
}
